import { describe, expect, it } from "vitest";
import { parseFeePercent } from "@/lib/fee";

describe("FE-9 parseFeePercent", () => {
  it("parses a percent string with a trailing % into a decimal fraction", () => {
    expect(parseFeePercent("1.5%")).toBe(0.015);
    expect(parseFeePercent("10%")).toBe(0.1);
    expect(parseFeePercent("0.8%")).toBe(0.008);
  });

  it("parses a bare number without a trailing % identically", () => {
    expect(parseFeePercent("1.5")).toBe(0.015);
  });

  it("throws on an empty string", () => {
    expect(() => parseFeePercent("")).toThrow();
  });

  it("throws on an unparseable/garbage string", () => {
    expect(() => parseFeePercent("abc")).toThrow();
  });

  it("round-trips every OB_MODEL_CATALOG seed string without throwing, always in (0, 1)", () => {
    const seeds = ["1.0%", "1.5%", "0.75%", "0.8%", "10%", "20%", "8%"];
    for (const s of seeds) {
      const n = parseFeePercent(s);
      expect(n).toBeGreaterThan(0);
      expect(n).toBeLessThan(1);
    }
  });
});
